(function() {
const canvas = document.getElementById('sorting-canvas');
const ctx = canvas.getContext('2d');
const options = { width: 500, height: 500, barCount: 50 };
let bars = [];
let sortingAlgorithm;
let animationFrame;
let continuous = true;
let comparisonCount = 0;
let swapCount = 0;
let recursiveDepth = 0;

function init() {
  canvas.width = options.width;
  canvas.height = options.height;
  bars = Array.from({ length: options.barCount }, (_, i) => ({ x: i * 10, height: Math.round(Math.random() * 100) }));
}

function scramble() {
  const pattern = document.querySelector('input[name="pattern"]:checked').value;
  switch (pattern) {
    case 'random':
      bars = bars.map(bar => ({ x: bar.x, height: Math.round(Math.random() * 100) }));
      break;
    case 'reverse':
      bars = bars.reverse();
      break;
    case 'nearly-sorted':
      bars = bars.map(bar => ({
        x: bar.x,
        height: bar.x * 10 + Math.round(Math.random() * 10)
      }));
      break;
  }
}

function drawBars() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  bars.forEach(bar => {
    if (bar.color) {
      ctx.fillStyle = bar.color;
    } else {
      ctx.fillStyle = 'blue';
    }
    const width = 6;
    const xOffset = (bar.x * (options.width - 1 - (options.barCount - 1) * width)) / (options.barCount - 1);
    const height = bar.height / 8 * options.height;
    ctx.fillRect(xOffset, options.height - height, width, height);
  });
}

function drawardematics(algorithm) {
  switch (algorithm) {
    case 'bubble':
    case 'heap':
      ctx.strokeStyle = 'white';
      ctx.strokeText(`${comparisonCount} comparisons`, 10, 20);
      ctx.strokeText `${swapCount} swaps`, 10, 40);
      break;
    case 'quick':
    case 'merge':
      ctx.strokeStyle = 'white';
      ctx.strokeText(`Depth: ${recursiveDepth}`, 10, 20);
      ctx.strokeText(`${comparisonCount} comparisons`, 10, 40);
      ctx.strokeText(`${swapCount} swaps`, 10, 60);
      break;
    case 'radix':
      ctx.strokeStyle = 'white';
      ctx.strokeText(`${comparisonCount} comparisons`, 10, 20);
      ctx.strokeText(`${swapCount} swaps`, 10, 40);
      break;
  }
}

function bubbleSort() {
  for (let i = bars.length - 1; i > 0; i--) {
    for (let j = 0; j < i; j++) {
      bars[j].color = 'red';
      bars[j + 1].color = 'red';
      if (bars[j].height > bars[j + 1].height) {
        [bars[j], bars[j + 1]] = [bars[j + 1], bars[j]];
        bars[j].color = 'yellow';
        bars[j + 1].color = 'yellow';
        swapCount++;
      }
      bars[j].color = null;
      bars[j + 1].color = null;
      comparisonCount++;
      if (!continuous) {
        drawBars();
        drawardematics('bubble');
        break;
      }
    }
    drawBars();
    drawardematics('bubble');
  }
}

